# ! [doc = " Centralized logic for parsing and attributes."] # ! [doc = ""] # ! [doc = " ## Architecture"] # ! [doc = " This crate is part of a series of crates and modules that handle attribute processing."] # ! [doc = " - [rustc_hir::attrs](https://doc.rust-lang.org/nightly/nightly-rustc/rustc_hir/index.html): Defines the data structures that store parsed attributes"] # ! [doc = " - [rustc_attr_parsing](https://doc.rust-lang.org/nightly/nightly-rustc/rustc_attr_parsing/index.html): This crate, handles the parsing of attributes"] # ! [doc = " - (planned) rustc_attr_validation: Will handle attribute validation, logic currently handled in `rustc_passes`"] # ! [doc = ""] # ! [doc = " The separation between data structures and parsing follows the principle of separation of concerns."] # ! [doc = " Data structures (`rustc_hir::attrs`) define what attributes look like after parsing."] # ! [doc = " This crate (`rustc_attr_parsing`) handles how to convert raw tokens into those structures."] # ! [doc = " This split allows other parts of the compiler to use the data structures without needing"] # ! [doc = " the parsing logic, making the codebase more modular and maintainable."] # ! [doc = ""] # ! [doc = " ## Background"] # ! [doc = " Previously, the compiler had a single attribute definition (`ast::Attribute`) with parsing and"] # ! [doc = " validation scattered throughout the codebase. This was reorganized for better maintainability"] # ! [doc = " (see [#131229](https://github.com/rust-lang/rust/issues/131229))."] # ! [doc = ""] # ! [doc = " ## Types of Attributes"] # ! [doc = " In Rust, attributes are markers that can be attached to items. They come in two main categories."] # ! [doc = ""] # ! [doc = " ### 1. Active Attributes"] # ! [doc = " These are attribute-like proc-macros that expand into other Rust code."] # ! [doc = " They can be either user-defined or compiler-provided. Examples of compiler-provided active attributes:"] # ! [doc = "   - `#[derive(...)]`: Expands into trait implementations"] # ! [doc = "   - `#[cfg()]`: Expands based on configuration"] # ! [doc = "   - `#[cfg_attr()]`: Conditional attribute application"] # ! [doc = ""] # ! [doc = " ### 2. Inert Attributes"] # ! [doc = " These are pure markers that don't expand into other code. They guide the compilation process."] # ! [doc = " They can be user-defined (in proc-macro helpers) or built-in. Examples of built-in inert attributes:"] # ! [doc = "   - `#[stable()]`: Marks stable API items"] # ! [doc = "   - `#[inline()]`: Suggests function inlining"] # ! [doc = "   - `#[repr()]`: Controls type representation"] # ! [doc = ""] # ! [doc = " ```text"] # ! [doc = "                      Active                 Inert"] # ! [doc = "              ┌──────────────────────┬──────────────────────┐"] # ! [doc = "              │     (mostly in)      │    these are parsed  │"] # ! [doc = "              │ rustc_builtin_macros │        here!         │"] # ! [doc = "              │                      │                      │"] # ! [doc = "              │    #[derive(...)]    │    #[stable()]       │"] # ! [doc = "     Built-in │    #[cfg()]          │    #[inline()]       │"] # ! [doc = "              │    #[cfg_attr()]     │    #[repr()]         │"] # ! [doc = "              │                      │                      │"] # ! [doc = "              ├──────────────────────┼──────────────────────┤"] # ! [doc = "              │                      │                      │"] # ! [doc = "              │                      │       `b` in         │"] # ! [doc = "              │                      │ #[proc_macro_derive( │"] # ! [doc = " User created │ #[proc_macro_attr()] │    a,                │"] # ! [doc = "              │                      │    attributes(b)     │"] # ! [doc = "              │                      │ ]                    │"] # ! [doc = "              └──────────────────────┴──────────────────────┘"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " ## How This Crate Works"] # ! [doc = " In this crate, syntactical attributes (sequences of tokens that look like"] # ! [doc = " `#[something(something else)]`) are parsed into more semantic attributes, markers on items."] # ! [doc = " Multiple syntactic attributes might influence a single semantic attribute. For example,"] # ! [doc = " `#[stable(...)]` and `#[unstable()]` cannot occur together, and both semantically define"] # ! [doc = " a \"stability\" of an item. So, the stability attribute has an"] # ! [doc = " [`AttributeParser`](attributes::AttributeParser) that recognizes both the `#[stable()]`"] # ! [doc = " and `#[unstable()]` syntactic attributes, and at the end produce a single"] # ! [doc = " [`AttributeKind::Stability`](rustc_hir::attrs::AttributeKind::Stability)."] # ! [doc = ""] # ! [doc = " When multiple instances of the same attribute are allowed, they're combined into a single"] # ! [doc = " semantic attribute. For example:"] # ! [doc = ""] # ! [doc = " ```rust"] # ! [doc = " #[repr(C)]"] # ! [doc = " #[repr(packed)]"] # ! [doc = " struct Meow {}"] # ! [doc = " ```"] # ! [doc = ""] # ! [doc = " This is equivalent to `#[repr(C, packed)]` and results in a single `AttributeKind::Repr`"] # ! [doc = " containing both `C` and `packed` annotations."] # ! [allow (internal_features)] # ! [doc (rust_logo)] # ! [feature (decl_macro)] # ! [feature (rustdoc_internals)] # ! [recursion_limit = "256"] use split_decls_genesis :: ourprelude :: * ; #[macro_use] #[doc = " All the individual attribute parsers for each of rustc's built-in attributes."] mod attributes ; #[doc = " All the important types given to attribute parsers when parsing"] pub (crate) mod context ; #[doc = " Code that other crates interact with, to actually parse a list (or sometimes single)"] #[doc = " attribute."] mod interface ; #[doc = " Despite this entire module called attribute parsing and the term being a little overloaded,"] #[doc = " in this module the code lives that actually breaks up tokenstreams into semantic pieces of attributes,"] #[doc = " like lists or name-value pairs."] pub mod parser ; mod lints ; mod session_diagnostics ; mod target_checking ; pub mod validate_attr ; pub use attributes :: cfg :: { CFG_TEMPLATE , EvalConfigResult , eval_config_entry , parse_cfg_attr } ; pub use attributes :: cfg_old :: * ; pub use attributes :: util :: { is_builtin_attr , is_doc_alias_attrs_contain_symbol , parse_version } ; pub use context :: { Early , Late , OmitDoc , ShouldEmit } ; pub use interface :: AttributeParser ; pub use lints :: emit_attribute_lint ; rustc_fluent_macro :: fluent_messages ! { "messages.ftl" }